import{_ as o,o as i,c as d,a2 as t}from"./chunks/framework.BN2sqjC1.js";const v=JSON.parse('{"title":"ADR-0025 — Build e dev server del frontend desktop con esbuild al posto di Vite","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0025-desktop-frontend-esbuild.md","filePath":"adr/0025-desktop-frontend-esbuild.md"}'),c={name:"adr/0025-desktop-frontend-esbuild.md"};function a(s,e,n,r,l,u){return i(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0025-—-build-e-dev-server-del-frontend-desktop-con-esbuild-al-posto-di-vite" tabindex="-1">ADR-0025 — Build e dev server del frontend desktop con esbuild al posto di Vite <a class="header-anchor" href="#adr-0025-—-build-e-dev-server-del-frontend-desktop-con-esbuild-al-posto-di-vite" aria-label="Permalink to &quot;ADR-0025 — Build e dev server del frontend desktop con esbuild al posto di Vite&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Data</strong></td><td>2026-10-28</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.7 (Excalidraw offline); ADR-0003 (stack), ADR-0005 (CSP), ADR-0010 (asset di Excalidraw)</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì, in modo puntuale: il bundler di <code>apps/desktop/frontend</code> e <code>web/</code> (lo spec e ADR-0003 indicano Vite)</td></tr></tbody></table><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> Il punto 3 (<code>frontend:dev:serverUrl</code> di Wails) non vale più: con Wails v3 il watcher di sviluppo (<code>wails3 tool watcher</code>, <code>apps/desktop/build/config.yml</code>) usa <code>FRONTEND_DEVSERVER_URL=http://127.0.0.1:5173</code>; <code>wails3 dev</code> non si usa perché impone <code>localhost</code> e una sua porta. Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Il frontend desktop era costruito e servito in sviluppo da Vite (con <code>@vitejs/plugin-react</code>). Si è chiesto di sostituirlo con esbuild. La stessa sostituzione è stata estesa a <code>web/</code> (Web UI incorporata nel binario cloud, vedi «Estensione a <code>web/</code>»); i pacchetti condivisi non hanno build proprie.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ol><li><code>scripts/esbuild.mjs</code> sostituisce <code>vite</code> e <code>vite build</code>: <code>build</code> produce <code>dist/</code> (ESM con code splitting, minificato, sourcemap collegate, nomi con hash); <code>dev</code> ricostruisce a ogni modifica, serve <code>dist/</code> su <code>127.0.0.1:5173</code> (porta configurabile) con un piccolo server HTTP proprio (quello di esbuild rifiuta l&#39;header <code>Host: wails.localhost</code> con cui Wails fa da proxy) e ricarica la pagina via <code>EventSource(&#39;/esbuild&#39;)</code>. Niente HMR: la pagina si ricarica per intero.</li><li>Ciò che Vite faceva implicitamente è esplicito nello script: <code>index.html</code> generato con bundle e CSS hashati, copia dei font di Excalidraw in <code>dist/excalidraw-assets/</code> (anche in dev, quindi senza middleware), import <code>?url</code> (worker di pdf.js) tramite un plugin, worker del grafo come bundle a parte in <code>dist/assets/layout.worker.js</code> (URL fisso, usato da <code>graph/layoutHost.ts</code>), <code>process.env.NODE_ENV</code> e <code>import.meta.env.MEMOBRAIN_E2E</code> definiti in build (prima <code>VITE_E2E</code>).</li><li>Wails non riconosce più il dev server da sé: <code>frontend:dev:serverUrl</code> è <code>http://127.0.0.1:5173</code> invece di <code>auto</code>.</li><li>Vitest resta (dipende da Vite, che quindi rimane come dipendenza transitiva solo dei test): <code>vitest.config.ts</code> sostituisce <code>vite.config.ts</code> e non usa più il plugin React. <code>src/env.d.ts</code> sostituisce <code>vite/client</code>.</li><li>Nuova dipendenza di sviluppo: <code>esbuild@0.28.2</code> (pubblicata il 2026-08-08).</li><li><strong>Release.</strong> In produzione non si emettono source map (<code>dist/</code> è incorporato nel binario con <code>go:embed</code>). <code>build</code> verifica un budget (<code>BUDGET</code> in <code>esbuild.mjs</code>): 2000 kB per ciò che si carica all&#39;avvio (entry e import statici, minificati) e 23000 kB per tutto l&#39;output senza i font di Excalidraw copiati; misure attuali 1880 e 21206 kB. Si alza un limite solo di proposito. <code>katex</code> è unico per tutta l&#39;app (alias sulla copia radice, prima c&#39;erano quattro copie); <code>mermaid</code> resta in tre versioni (10.9.3 del convertitore, 11.x di Excalidraw, 12.2 diretta), da rivalutare con la questione aperta di ADR-0024.</li><li><strong>Gate sul bundle di produzione.</strong> <code>node scripts/esbuild.mjs preview</code> costruisce il bundle di produzione in <code>node_modules/.preview/</code> e lo serve; <code>yarn e2e:prod</code> (<code>make e2e-desktop-prod</code>, incluso in <code>make e2e</code>) esegue su di esso gli spec di disegni, grafo e canvas, così problemi di chunk, interop CommonJS o CSP emergono prima del rilascio.</li><li>Le importazioni dinamiche di moduli CommonJS con code splitting danno solo <code>default</code>: MathJax (<code>drawing/latex/tex2svg.ts</code>) le legge da lì quando i nomi mancano.</li></ol><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>Build più semplice e veloce; nessun HMR in sviluppo (reload completo, stato dell&#39;app perso a ogni modifica).</li><li>Lo script è codice nostro da mantenere; la CSP non cambia (il reload in sviluppo usa un file <code>dev-reload.js</code>, non script inline).</li><li>ADR-0003 (Vite 8), ADR-0005 (dev server Vite) e ADR-0010 (plugin Vite per gli asset) restano come storia: per il desktop valgono le decisioni qui sopra. Aggiornare lo spec è a cura dell&#39;owner.</li></ul><h2 id="estensione-a-web" tabindex="-1">Estensione a <code>web/</code> <a class="header-anchor" href="#estensione-a-web" aria-label="Permalink to &quot;Estensione a `web/`&quot;">​</a></h2><p><code>web/scripts/esbuild.mjs</code> sostituisce <code>vite</code>/<code>vite build</code>/<code>vite preview</code> e <code>web/vite-plugin-sri.ts</code>:</p><ul><li><code>build</code> produce <code>dist/</code> (ESM con splitting, minificato, <strong>nessuna sourcemap</strong>: <code>dist/</code> è incorporata con <code>go:embed</code>) e controlla il budget (ADR-0020: chunk iniziale ≤ 700 kB, totale ≤ 1000 kB; misurati 599/608 kB).</li><li>L&#39;SRI (<code>integrity</code> sha384 + <code>crossorigin</code>) è calcolata dal plugin <code>index-html</code> sui byte scritti in <code>dist/</code>; in dev non c&#39;è. <code>index.html</code> non contiene script né stili inline (CSP del cloud).</li><li><code>dev [--port N]</code> serve <code>dist/</code> su <code>127.0.0.1:5174</code>, con fallback SPA a <code>index.html</code> per le rotte di react-router, proxy di <code>/api</code> verso il cloud (<code>MEMOBRAIN_API</code>, default <code>http://127.0.0.1:18081</code>) e live reload via <code>EventSource(&#39;/esbuild&#39;)</code>.</li><li><code>VITE_E2E</code> diventa <code>MEMOBRAIN_E2E</code> (<code>define</code>): il doppio OIDC resta fuori dai build di produzione (verificato con <code>grep -r memobrain.e2e web/dist</code>).</li><li>Verifiche: tipi, 59 e2e Playwright sul dev server e <code>e2e:security</code> (CSP, SRI, nessuna richiesta cross-origin) sul build di produzione servito dall&#39;handler incorporato.</li></ul>',12)])])}const m=o(c,[["render",a]]);export{v as __pageData,m as default};
